    TEXT.put("From center: 5 semitones right, then left", new String[]{"Ab Mitte: 5 Halbtöne rechts, dann links","От середины: 5 полутонов вправо, затем влево","Depuis le centre : 5 demi-tons à droite, puis à gauche","Desde el centro: 5 semitonos a la derecha y después a la izquierda"});
    TEXT.put("From center: 5 whole tones right, then left", new String[]{"Ab Mitte: 5 Ganztöne rechts, dann links","От середины: 5 целых тонов вправо, затем влево","Depuis le centre : 5 tons à droite, puis à gauche","Desde el centro: 5 tonos a la derecha y después a la izquierda"});
