    TEXT.put("Standard tuning restored.", new String[]{"Standardstimmung wiederhergestellt.","Стандартный строй восстановлен.","Accord standard rétabli.","Afinación estándar restaurada."});
    TEXT.put("Standard ukulele: floor to ceiling A–E–C–G, all in the one-line octave. G is string 4 on the ceiling side. Play one open string at a time.", new String[]{"Standard-Ukulele: vom Boden zur Decke A–E–C–G in der eingestrichenen Oktave. G ist Saite 4 zur Decke. Jeweils eine leere Saite spielen.","Стандартное укулеле: от пола A–E–C–G первой октавы. Соль — четвёртая струна со стороны потолка. Играйте по одной открытой струне.","Ukulélé standard : du sol au plafond, la–mi–do–sol dans l’octave 4. Sol est la corde 4 côté plafond. Jouez une corde à vide à la fois.","Ukelele estándar: desde el suelo, la–mi–do–sol en la octava 4. Sol es la cuerda 4 hacia el techo. Toque una cuerda al aire cada vez."});
    TEXT.put("Standard, floor upward: A E C G", new String[]{"Standard, vom Boden aufwärts: A E C G","Обычный, снизу от пола: A E C G","Standard, depuis le sol : la mi do sol","Estándar, desde el suelo: la mi do sol"});
    TEXT.put("Standard: floor to ceiling A–E–C–G", new String[]{"Standard: vom Boden zur Decke A–E–C–G","Стандарт: от пола A–E–C–G","Standard, du sol au plafond : la–mi–do–sol","Estándar, desde el suelo: la–mi–do–sol"});
