    TEXT.put("Stroik profile (*.json)|*.json", new String[]{"Stroik-Profil (*.json)|*.json","Профиль Stroik (*.json)|*.json","Profil Stroik (*.json)|*.json","Perfil de Stroik (*.json)|*.json"});
    TEXT.put("Stroik {0} — accessible tuner", new String[]{"Stroik {0} — barrierefreies Stimmgerät","Stroik {0} — доступный тюнер","Stroik {0} — accordeur accessible","Stroik {0} — afinador accesible"});
    TEXT.put("Stroik {0}. Accessible tuner for blind, partially sighted and sighted musicians. Tuning fork, microphone and ear-training practice. Created by Proszczok with Codex. Original idea: Witold.", new String[]{"Stroik {0}. Zugängliches Stimmgerät für blinde, sehbehinderte und sehende Musiker. Stimmgabel, Mikrofon und Gehörbildung. Erstellt von Proszczok mit Codex. Idee: Witold.","Stroik {0}. Доступный тюнер для незрячих, слабовидящих и зрячих музыкантов. Камертон, микрофон и обучение настройке на слух. Разработчик: Proszczok с Codex. Автор идеи: Witold.","Stroik {0}. Accordeur accessible aux musiciens aveugles, malvoyants et voyants. Diapason, microphone et entraînement de l’oreille. Réalisé par Proszczok avec Codex. Idée originale : Witold.","Stroik {0}. Afinador accesible para músicos ciegos, con baja visión y videntes. Diapasón, micrófono y entrenamiento auditivo. Creado por Proszczok con Codex. Idea original: Witold."});
    TEXT.put("Stroik — fork calibrator", new String[]{"Stroik — Stimmgabelkalibrator","Stroik — калибратор камертона","Stroik — calibrateur du diapason","Stroik — calibrador del diapasón"});
