    TEXT.put("Stroik. Screen reader announcements work.", new String[]{"Stroik. Screenreader-Ansagen funktionieren.","Stroik. Сообщения программы экранного доступа работают.","Stroik. Les annonces du lecteur d’écran fonctionnent.","Stroik. Los anuncios del lector de pantalla funcionan."});
