    TEXT.put("Tuning order", new String[]{"Stimmreihenfolge","Порядок настройки","Ordre d’accordage","Orden de afinación"});
    TEXT.put("Tuning parameters", new String[]{"Stimmparameter","Параметры настройки","Paramètres d’accordage","Parámetros de afinación"});
    TEXT.put("Two clear components not found. Try separate measurement.", new String[]{"Keine zwei klaren Komponenten erkannt. Getrennte Messung versuchen.","Не найдены две чёткие составляющие. Попробуйте измерить отдельно.","Deux composantes nettes introuvables. Essayez une mesure séparée.","No se encontraron dos componentes claros. Pruebe la medición por separado."});
    TEXT.put("Two components not found. Try separately.", new String[]{"Zwei Komponenten nicht gefunden. Versuchen Sie es getrennt.","Два компонента не найдены. Попробуйте сыграть отдельно.","Deux composantes introuvables. Essayez séparément.","No se encontraron dos componentes. Pruebe por separado."});
    TEXT.put("Two strikes advance to the next note in the selected order", new String[]{"Zwei Anschläge wechseln zum nächsten Ton der gewählten Reihenfolge","Два удара переходят к следующей ноте выбранной последовательности","Deux frappes passent à la note suivante de l’ordre choisi","Dos golpes pasan a la nota siguiente del orden elegido"});
    TEXT.put("Ukulele", new String[]{"Ukulele","Укулеле","Ukulélé","Ukelele"});
    TEXT.put("Ukulele tuning", new String[]{"Ukulele-Stimmung","Строй укулеле","Accordage du ukulélé","Afinación del ukelele"});
    TEXT.put("Ukulele tuning:", new String[]{"Ukulelestimmung:","Строй укулеле:","Accordage de l’ukulélé :","Afinación del ukelele:"});
    TEXT.put("Up and Down arrows change the value.", new String[]{"Pfeil nach oben oder unten ändert den Wert.","Стрелки вверх и вниз изменяют значение.","Les flèches haut et bas changent la valeur.","Las flechas arriba y abajo cambian el valor."});
    TEXT.put("Update error", new String[]{"Updatefehler","Ошибка обновления","Erreur de mise à jour","Error de actualización"});
